const lessonSpecs = lessons.map((item) => ({ id: item[0], level: item[1], title: item[2], meta: item[3], atoms: item[4] }));
const sectionSpecs = [
  ['forms-foundation','定义、本质与报告骨架','Definition, core and reporting frames','先分清原话与转述的边界，再掌握标点、陈述转述和 say/tell 基本搭配。','Distinguish exact quotation from reported meaning, then master punctuation, statement reporting and core say/tell patterns.',['reported-speech-essence','direct-form-punctuation','reported-form-foundation','statements-that','say-tell-verbs']],
  ['sentence-types','不同句型的转述','Reporting different sentence types','系统转述一般疑问、特殊疑问、命令、请求、建议、感叹和回应。','Report yes-no and wh-questions, commands, requests, suggestions, exclamations and responses.',['yes-no-questions','wh-questions','commands-requests','advice-suggestion','exclamations-responses']],
  ['tense-backshift','时态与情态后移','Tense and modal backshift','建立现在、过去、将来和情态动词的后移对应。','Build backshift correspondences for present, past, future and modal forms.',['backshift-present','backshift-past-future','modal-changes']],
  ['backshift-boundaries','时态不后移的边界','Boundaries of no backshift','区分客观事实、仍然成立和即时转述，不机械后移。','Distinguish general truths, still-valid content and immediate reporting without mechanical backshift.',['no-backshift-boundaries']],
  ['reference-deixis','人称与时空指示','Person and spatiotemporal deixis','按说话人、听话人、时间点和地点重建代词与指示词。','Rebuild pronouns and deictic terms from speaker, addressee, time and place.',['person-possessive','deictic-time-place']],
  ['writing-restoration','书写位置与反向还原','Writing position and reverse restoration','处理报告语的前、中、后位置，并从间接引语重建说话现场。','Handle initial, medial and final reporting clauses and reconstruct speech situations from indirect reports.',['reporting-clause-position','indirect-to-direct']],
  ['complex-integration','多层转述与综合改写','Layered reporting and integrated rewriting','处理多层视点、指代歧义、报告动词立场和综合改写。','Handle layered viewpoints, reference ambiguity, reporting-verb stance and integrated rewriting.',['layered-reporting','ambiguity-boundaries','integrated-rewrite']]
];

function validate(course, sections) {
  const ids = course.map((lesson) => lesson.id);
  const assigned = sections.flatMap((section) => section.lessonIds);
  if (new Set(ids).size !== ids.length || assigned.length !== ids.length || new Set(assigned).size !== assigned.length || ids.some((id) => !assigned.includes(id)) || assigned.some((id) => !ids.includes(id))) throw new Error('Invalid reported-speech section coverage');
  if (ids[0] !== 'reported-speech-essence' || !course[0].title.match(/定义|Definition/)) throw new Error('Reported-speech course must begin with definition and core boundaries');
  course.forEach((lesson) => {
    if (lesson.rules.length < 3 || lesson.examples.length !== lesson.rules.length || lesson.questions.length !== lesson.rules.length || lesson.analyses.length !== lesson.rules.length || lesson.exampleNotes.length !== lesson.rules.length) throw new Error(`Incomplete reported-speech lesson: ${lesson.id}`);
    lesson.analyses.forEach((analysis) => { if (!analysis.length || analysis.some((item) => !item.text || !item.role || !item.label)) throw new Error(`Invalid analysis: ${lesson.id}`); });
    if (lesson.analyses.some((analysis) => analysis.some((item) => item.role === 'complement' || item.label === '补足成分'))) throw new Error(`Vague component label: ${lesson.id}`);
    if (lesson.exampleNotes.some((item) => !item.visible || !item.body || !item.title)) throw new Error(`Missing concrete example explanation: ${lesson.id}`);
    lesson.questions.forEach((item) => {
      if (!item.question || item.options.length !== 2 || !['A','B'].includes(item.answer) || !item.options.some((option) => option.key === item.answer) || !item.correct || !item.wrong) throw new Error(`Invalid question: ${lesson.id}`);
    });
    if (INCLUDE_RULE_COVERAGE) {
      if (lesson.ruleCoverage.length !== lesson.rules.length) throw new Error(`Invalid coverage count: ${lesson.id}`);
      lesson.ruleCoverage.forEach((coverage, i) => { if (!coverage.exampleIndexes.length || !coverage.questionIndexes.length || coverage.exampleIndexes.some((n) => n < 0 || n >= lesson.examples.length) || coverage.questionIndexes.some((n) => n < 0 || n >= lesson.questions.length)) throw new Error(`Invalid coverage: ${lesson.id}:${i}`); });
    }
  });
  const suggestLesson = course.find((lesson) => lesson.id === 'advice-suggestion');
  if (!suggestLesson || !suggestLesson.rules.some((rule) => rule.includes('suggest sb to do')) || !suggestLesson.rules.some((rule) => rule.includes('doing')) || !suggestLesson.rules.some((rule) => /暗示|indicate/.test(rule)) || !suggestLesson.questions.some((item) => item.options.some((option) => option.text.includes('suggested us to')))) throw new Error('Missing suggest-pattern boundary');
}

function buildReportedSpeechCourse(english) {
  const course = lessonSpecs.map((spec, index) => makeLesson(english, spec, index));
  const sections = sectionSpecs.map((item) => ({ id: item[0], title: pick(english, item[1], item[2]), copy: pick(english, item[3], item[4]), lessonIds: item[5].slice(), lessonCount: item[5].length }));
  validate(course, sections);
  const core = course.filter((lesson) => lesson.level === 'core');
  const advanced = course.filter((lesson) => lesson.level === 'advanced');
  return {
    title: pick(english, `直接引语与间接引语 · ${course.length} 节微课`, `Direct and reported speech · ${course.length} lessons`),
    copy: pick(english, '从句型和报告动词出发，系统处理语序、时态、人称、时空指示和多层视点。','Start from sentence type and reporting verbs, then handle order, tense, person, deixis and layered viewpoints.'),
    course, sections,
    groups: [
      { id: 'core', title: pick(english, `核心必学 · ${core.length} 节`, `Core · ${core.length} essential lessons`), copy: pick(english, '掌握高频转述骨架和必要的时态、指代调整。','Master high-frequency reporting frames and essential tense and reference changes.'), lessons: core },
      { id: 'advanced', title: pick(english, `进阶挑战 · ${advanced.length} 节`, `Advanced · ${advanced.length} challenge lessons`), copy: pick(english, '处理书写位置、反向还原、多层转述、歧义和综合改写。','Handle reporting-clause position, reverse restoration, layered reports, ambiguity and integrated rewriting.'), lessons: advanced }
    ]
  };
}

module.exports = { buildReportedSpeechCourse };
